import java.util.ArrayList;
import java.util.List;
import java.util.function.Supplier;

public class ReferenceToolkitTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        checkCall("parseDecimal on 42", 42, () -> ReferenceToolkit.parseDecimal().apply("42"));
        checkCall("parseDecimal on -7", -7, () -> ReferenceToolkit.parseDecimal().apply("-7"));
        checkCall("trimmer on padded text", "hi", () -> ReferenceToolkit.trimmer().apply("  hi  "));
        checkCall("trimmer on already-clean text", "hi", () -> ReferenceToolkit.trimmer().apply("hi"));

        List<String> tracked = new ArrayList<>();
        Supplier<Integer> size = ReferenceToolkit.sizeOf(tracked);
        checkCall("bound supplier on an empty list", 0, () -> size.get());
        tracked.add("a");
        tracked.add("b");
        checkCall("bound supplier sees later changes", 2, () -> size.get());

        checkCall("listMaker makes an empty list", true, () -> ReferenceToolkit.listMaker().get().isEmpty());
        checkCall("listMaker makes a NEW list each call", true, () -> {
            Supplier<List<String>> maker = ReferenceToolkit.listMaker();
            List<String> one = maker.get();
            List<String> two = maker.get();
            one.add("x");
            return one != two && two.isEmpty();
        });

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

