import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.function.Supplier;

public class ReferenceToolkit {

    public static Function<String, Integer> parseDecimal() {
        return Integer::parseInt;
    }

    public static Function<String, String> trimmer() {
        return String::trim;
    }

    public static Supplier<Integer> sizeOf(List<String> list) {
        return list::size;
    }

    public static Supplier<List<String>> listMaker() {
        return ArrayList::new;
    }
}
